Route::get('/',[SearchController::class,'home'])->name('home');Route::get('/search',[SearchController::class,'search'])->name('search');Route::get('/company/{sponsor:slug}',[SearchController::class,'company'])->name('company.show');Route::middleware(['auth','can:admin'])->prefix('admin')->name('admin.')->group(function(){Route::get('/',[DashboardController::class,'index'])->name('dashboard');Route::post('/import',[DashboardController::class,'import'])->name('import');});Route::view('/robots.txt','robots')->name('robots');Route::get('/sitemap.xml',fn()=>response()->view('sitemap',['sponsors'=>\App\Models\Sponsor::latest('updated_at')->limit(50000)->get()])->header('Content-Type','application/xml'));
